from lib import *
S = SS('t9')
steps = [
    step("补偿也会失败。支付失败后补偿“释放库存”,释放这一步恰好遇到临时错误;朴素编排器 try/except 记一行日志就继续往下走,订单被改成 CANCELLED,可库存预留还是 RESERVED(库存 99、预留中 1):这件商品被一个已取消的订单占着。放大到 400 单(20% 支付失败、释放有 10% 概率临时失败):支付失败 94 单,其中补偿失败 9 单,对账出来“已取消但仍占库存”的 9 单(期望约 8)。补偿失败如果被吞掉,就是一笔永久的库存泄漏。", t=tl(S(1)), mark=lidx(S(1), '补偿 stock_release 失败', '对账出来'), done=lidx(S(1), '对账:订单已经 CANCELLED'), b=bars([['支付失败的订单', 94, '94'], ['其中补偿失败(库存泄漏)', 9, '9']], 100, mark=[1], cur=[0]), kv=KV([['补偿失败被吞掉', '订单 CANCELLED,预留仍 RESERVED'], ['400 单', '94 单支付失败,9 单泄漏'], ['对账', '订单状态 vs 预留状态']], ['补偿失败被吞掉'])),
    step("补偿要重试到成功。前 3 次调用失败,指数退避(50 ms 起、每次翻倍):第 1 次失败后等 50 ms,第 2 次(55.1 ms)失败后等 100 ms,第 3 次(157.5 ms)失败后等 200 ms,第 4 次(363.0 ms)成功,库存回到 100。服务整体挂 2 秒后恢复:固定间隔 100 ms 的重试调用了 21 次、恢复后 82 ms 补偿成功;指数退避调用了 7 次、恢复后 576 ms 才成功——次数少、但最多要多等一个退避间隔。重试意味着补偿可能被执行多次(响应丢了就会重发),所以补偿必须幂等:带状态检查的释放调用 3 次,库存仍是 100;直接 qty = qty + 1 的释放调用 3 次,库存变成 102。", t=tl(S(2)), mark=lidx(S(2), '第 4 次:成功', '库存 102'), done=lidx(S(2), '固定间隔 100 ms', '库存 100(预留中 0)'), b=bars([['固定间隔:2 秒内调用次数', 21, '21'], ['指数退避:2 秒内调用次数', 7, '7'], ['非幂等释放 3 次后的库存', 102, '102(应为 100)']], 110, cur=[0, 1], mark=[2]), kv=KV([['固定间隔', '21 次调用,恢复后 82 ms 成功'], ['指数退避', '7 次调用,恢复后 576 ms 成功'], ['补偿要幂等', '重试会让同一个补偿执行多次']], ['补偿要幂等'])),
    step("补偿不是回滚。支付扣了 1 元手续费(不退),订单创建时发过一条“下单成功”的短信;后面失败时补偿只能退款加再发一条取消短信。对比 Saga 之前和补偿之后:库存 100 → 100,相同;用户余额 10000 → 9999,少了 1(手续费不退);已发出的短信 0 → 2 条,多了 2 条(发出去的撤不回来);支付记录 0 → 1 行,留下一行 REFUNDED 作审计。补偿把能撤的撤回来了,撤不回来的(手续费、已发出的短信)只能用新的动作去抵消或解释。", t=tl(S(3)), mark=lidx(S(3), '用户余额', '已发出的短信条数'), done=lidx(S(3), '库存       |', '扣款后余额'), b=bars([['补偿后余额与初始的差', 1, '1(手续费)'], ['补偿后多出的短信', 2, '2 条'], ['补偿后多出的支付记录', 1, '1 行']], 2, mark=[0, 1], cur=[2]), kv=KV([['库存', '回到初始值'], ['余额', '少了手续费 1'], ['短信', '多了 2 条,撤不回来']], ['短信'])),
    step("有些补偿永远不会成功(比如要退款的账户已经注销),重试没有意义。300 个 saga(25% 支付失败,补偿遇到 15% 临时错误、4% 永久失败):CONFIRMED 232 个,CANCELLED 65 个(补偿尝试 83 次,临时错误重试后成功),COMPENSATION_FAILED 3 个(各尝试 1 次就判定永久失败)。这 3 个进入 manual_queue(s-51、s-89、s-146,步骤 stock_release)。对账:订单停在 CANCELLING 且库存仍被占着的正好 3 笔,和队列行数一致——这部分要靠人或专门的修复任务收尾,而不是让 saga 无限重试。", t=tl(S(4)), mark=lidx(S(4), 'COMPENSATION_FAILED', 's-51'), done=lidx(S(4), 'CANCELLED  ', 'manual_queue 共 3 行'), b=bars([['CONFIRMED', 232, '232'], ['CANCELLED(补偿成功)', 65, '65'], ['COMPENSATION_FAILED(人工队列)', 3, '3']], 240, done=[0, 1], mark=[2]), kv=KV([['临时错误', '重试到成功(65 个取消的 saga)'], ['永久失败', '1 次判定,进人工队列(3 个)'], ['对账', '队列行数 = 仍被占库存的订单数']], ['永久失败'])),
    step("步骤顺序决定补偿的负担。不可补偿的动作(发“下单成功”通知)放在最前面(A:通知 → 库存 → 支付),后面支付一失败就撤不回来:300 个 saga 里 81 个订单发了“下单成功”却被取消。放到支付成功之后(B:库存 → 支付 → 通知):这样的订单是 0 个,通知自己遇到 30% 的临时失败就一直重试,平均 1.42 次尝试,没有 CONFIRMED 订单漏发通知。两种顺序面对的是完全相同的 300 次“支付是否失败”,最终 CONFIRMED 都是 219 个。把不能补偿的步骤放在不会再失败的“转折点”之后,它失败只需要向前重试,不需要回头补偿别的步骤。", t=tl(S(5)), mark=lidx(S(5), 'A:通知 → 库存 → 支付'), done=lidx(S(5), 'B:库存 → 支付 → 通知'), b=bars([['A 发了通知却被取消', 81, '81'], ['B 发了通知却被取消', 0, '0'], ['A 通知平均尝试', 1.42, '1.42'], ['B 通知平均尝试', 1.42, '1.42']], 90, mark=[0], done=[1], cur=[2, 3]), kv=KV([['A(通知在前)', '81 个订单发了通知又被取消'], ['B(通知在后)', '0 个,通知失败只重试'], ['原则', '不可补偿的步骤放在转折点之后']], ['原则'])),
]
A = mkartt('t9', 9, '分布式事务,Saga,补偿,重试,幂等,人工队列,MySQL,真实验证,动画演示',
    '实测 Saga 补偿失败怎么办:被吞掉的补偿失败让 400 单里 9 单永久占着库存;指数退避重试 2 秒内 7 次调用(固定间隔 21 次),补偿不幂等会把库存加成 102;补偿不是回滚(手续费、短信撤不回);永久失败进人工队列 3 个;不可补偿步骤放前面 81 个订单发了通知又被取消。',
    'Saga 靠补偿代替回滚。补偿本身失败了怎么办?怎么重试?补偿能把世界恢复原样吗?永远失败的补偿放哪?不可补偿的动作该排在哪一步?这篇用订单、库存、支付三个服务,把这五个问题逐个跑出来。',
    [('9 / 400', '补偿失败被吞掉时,400 单里留下“已取消却仍占库存”的订单数'), ('21 对 7', '服务挂 2 秒时,补偿重试的调用次数:固定间隔 100 ms 对指数退避'), ('81 / 0', '300 个 saga 里,通知放在最前面与放在支付成功之后,“下单成功”通知发出却被取消的订单数')],
    [('补偿失败别吞掉', '<p>补偿遇到临时错误,朴素写法只记日志就继续,订单取消了、预留还在。必须把补偿当成一个需要保证完成的动作。</p>'),
     ('重试与幂等', '<p>补偿用指数退避重试到成功;服务恢复后可能多等一个退避间隔,但不会把恢复中的服务打满。重试意味着补偿会被多次执行,所以要幂等。</p>'),
     ('补偿不等于回滚', '<p>手续费不退、短信发出就撤不回,补偿只能用新的动作去抵消,留下审计记录。Saga 之后的世界和之前不完全相同。</p>'),
     ('永久失败进人工队列', '<p>永远不会成功的补偿(账户注销等)重试没有意义,要判定为永久失败,放进人工处理队列,并让对账能找到它们。</p>'),
     ('不可补偿的步骤放后面', '<p>把发通知这类不可补偿的动作放在转折点(支付成功)之后,它失败只需向前重试,不会出现“通知发了但订单取消”。</p>')],
    steps,
    [ENV_T + '。本篇三个服务的库是同一个 MySQL 26.7.0 实例里的 schema,编排器自己的 saga_log、manual_queue 在 saga_db;临时错误与永久失败是用 shop.inject() 在服务调用里按次数或概率注入的(固定随机种子);“服务挂 2 秒”是让服务在 2 秒内抛临时错误;重试间隔用的是真实 sleep',
     '没有验证:编排器自己崩溃后,从 saga_log 恢复并继续补偿(第 30 篇再做);补偿的并行执行与顺序依赖;真实支付渠道的退款规则;重试风暴下游被打满的真实表现(这里只数了调用次数);各概率(15% 临时、4% 永久、25% 支付失败)是我设的,不是真实业务统计'],
    'Saga 的补偿')
